struct RingBuffer {
    int data[1024];
    int head;
    int tail;
    int count;
    int capacity;

    RingBuffer(int capacity) : head(0), tail(0), count(0), capacity(capacity) {}

    bool push(int value) {
        if (count == capacity) {
            return false;
        }
        data[tail] = value;
        tail = (tail + 1) % capacity;
        count++;
        return true;
    }

    bool pop(int& out) {
        if (count == 0) {
            return false;
        }
        out = data[head];
        head = (head + 1) % capacity;
        count--;
        return true;
    }

    int size() const {
        return count;
    }

    bool empty() const {
        return count == 0;
    }

    bool full() const {
        return count == capacity;
    }
};

