                sum += W1[j * n_in + k] * x[k];
            }
            h_val = tanh(sum);
            z_val += W2[j] * h_val;
        }

        double p = 1.0 / (1.0 + exp(-z_val));

        // Loss
        // loss = -( y*log(p) + (1-y)*log(1-p) )
        // Avoid log(0)
        double eps = 1e-15;
        double p_safe = p;
        if (p_safe < eps) p_safe = eps;
        if (p_safe > 1.0 - eps) p_safe = 1.0 - eps;

        double loss = -(target * log(p_safe) + (1.0 - target) * log(1.0 - p_safe));
        total_loss += loss;

        // Backward pass
        // dL/dz = p - y
        double dz = p - target;

        // dL/dW2[j] = dz * h_j
        // dL/db2 = dz

        // We need h_j again. Let's recompute h.
        for (int j = 0; j < n_hidden; ++j) {
            double sum = b1[j];
            for (int k = 0; k < n_in; ++k) {
                sum += W1[j * n_in + k] * x[k];
            }
            h_val = tanh(sum);

            gW2[j] += dz * h_val;

            // dL/dh_j = dz * W2[j]
            double dh = dz * W2[j];

            // dL/d(sum_j) = dh * (1 - h_j^2)
            double dsum = dh * (1.0 - h_val * h_val);

            gb1[j] += dsum;

            for (int k = 0; k < n_in; ++k) {
                gW1[j * n_in + k] += dsum * x[k];
            }
        }

        gb2[0] += dz;
    }

    // Average loss and gradients
    double inv_n = 1.0 / n_samples;
    total_loss *= inv_n;

    for (int i = 0; i < w1_size + b1_size + w2_size + b2_size; ++i) {
        grad[i] *= inv_n;
    }

    return total_loss;
}
