struct Tape {
    struct Node {
        double value;
        double grad;
        int op; // 0: constant/input, 1: add, 2: mul, 3: sin, 4: exp
        int a;
        int b;
    };

    std::vector<Node> nodes;

    int constant(double v) {
        nodes.push_back({v, 0.0, 0, -1, -1});
        return (int)nodes.size() - 1;
    }

    int input(double v) {
        nodes.push_back({v, 0.0, 0, -1, -1});
        return (int)nodes.size() - 1;
    }

    int add(int a, int b) {
        double val = nodes[a].value + nodes[b].value;
        nodes.push_back({val, 0.0, 1, a, b});
        return (int)nodes.size() - 1;
    }

    int mul(int a, int b) {
        double val = nodes[a].value * nodes[b].value;
        nodes.push_back({val, 0.0, 2, a, b});
        return (int)nodes.size() - 1;
    }

    int sin_(int a) {
        double val = std::sin(nodes[a].value);
        nodes.push_back({val, 0.0, 3, a, -1});
        return (int)nodes.size() - 1;
    }

    int exp_(int a) {
        double val = std::exp(nodes[a].value);
        nodes.push_back({val, 0.0, 4, a, -1});
        return (int)nodes.size() - 1;
    }

    double value(int node) const {
        return nodes[node].value;
    }

    void backward(int root) {
        // Reset gradients
        for (auto& n : nodes) {
            n.grad = 0.0;
        }
        nodes[root].grad = 1.0;

        // Reverse sweep: iterate from root down to 0
        // Since nodes are recorded in topological order (parents after children),
        // iterating backwards ensures consumers are processed before inputs.
        for (int i = root; i >= 0; --i) {
            const Node& n = nodes[i];
            double g = n.grad;
            if (g == 0.0) continue;

            if (n.op == 1) { // add
                nodes[n.a].grad += g;
                nodes[n.b].grad += g;
            } else if (n.op == 2) { // mul
                nodes[n.a].grad += g * nodes[n.b].value;
                nodes[n.b].grad += g * nodes[n.a].value;
            } else if (n.op == 3) { // sin
                nodes[n.a].grad += g * std::cos(nodes[n.a].value);
            } else if (n.op == 4) { // exp
                nodes[n.a].grad += g * nodes[i].value; // exp(x)' = exp(x)
            }
        }
    }

    double grad(int node) const {
        return nodes[node].grad;
    }
};
