module async_fifo #(parameter WIDTH = 8, parameter DEPTH = 8)
  (input wclk, input wrst_n, input winc, input [WIDTH-1:0] wdata, output wfull,
   input rclk, input rrst_n, input rinc, output [WIDTH-1:0] rdata, output rempty);

  localparam PTR_WIDTH = $clog2(DEPTH);
  localparam PTR_WIDTH_PLUS_1 = PTR_WIDTH + 1;

  // Memory
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  // Write domain signals
  reg [PTR_WIDTH_PLUS_1-1:0] wptr_bin;
  reg [PTR_WIDTH_PLUS_1-1:0] wptr_gray;
  reg [PTR_WIDTH_PLUS_1-1:0] rptr_gray_sync1;
  reg [PTR_WIDTH_PLUS_1-1:0] rptr_gray_sync2;
  reg [PTR_WIDTH_PLUS_1-1:0] rptr_gray_sync3; // Extra stage for full detection stability if needed, but 2 is standard. 
  // Actually, standard 2-flop sync is sufficient. Let's stick to 2-flop sync for the pointer crossing.
  // We need to synchronize the read pointer (gray) into the write domain.
  // We need to synchronize the write pointer (gray) into the read domain.

  // Read domain signals
  reg [PTR_WIDTH_PLUS_1-1:0] rptr_bin;
  reg [PTR_WIDTH_PLUS_1-1:0] rptr_gray;
  reg [PTR_WIDTH_PLUS_1-1:0] wptr_gray_sync1;
  reg [PTR_WIDTH_PLUS_1-1:0] wptr_gray_sync2;

  // Next pointers
  wire [PTR_WIDTH_PLUS_1-1:0] wptr_bin_next;
  wire [PTR_WIDTH_PLUS_1-1:0] wptr_gray_next;
  wire [PTR_WIDTH_PLUS_1-1:0] rptr_bin_next;
  wire [PTR_WIDTH_PLUS_1-1:0] rptr_gray_next;

  // Write logic
  assign wptr_bin_next = wptr_bin + (winc & ~wfull);
  assign wptr_gray_next = (wptr_bin_next >> 1) ^ wptr_bin_next;

  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr_bin <= 0;
      wptr_gray <= 0;
      rptr_gray_sync1 <= 0;
      rptr_gray_sync2 <= 0;
    end else begin
      wptr_bin <= wptr_bin_next;
      wptr_gray <= wptr_gray_next;
      rptr_gray_sync1 <= rptr_gray;
      rptr_gray_sync2 <= rptr_gray_sync1;
    end
  end

  // Write memory
  always @(posedge wclk) begin
    if (winc & ~wfull) begin
      mem[wptr_bin[PTR_WIDTH-1:0]] <= wdata;
    end
  end

  // Full detection
  // FIFO is full when the write pointer is exactly one full cycle ahead of the read pointer.
  // In Gray code, this means the MSB and MSB-1 are inverted, and the rest are equal.
  wire [PTR_WIDTH_PLUS_1-1:0] wfull_next;
  assign wfull_next = (wptr_gray_next == {~rptr_gray_sync2[PTR_WIDTH_PLUS_1-1:PTR_WIDTH_PLUS_1-2], rptr_gray_sync2[PTR_WIDTH_PLUS_1-3:0]});

  // Wait, the condition for full in Gray code:
  // If we have N bits (including the extra bit for wrap-around detection),
  // Full is when wptr_gray == {~rptr_gray[N-1:N-2], rptr_gray[N-3:0]}
  // Let's verify with DEPTH=8, PTR_WIDTH=3, PTR_WIDTH_PLUS_1=4.
  // Indices 3,2,1,0.
  // Full when wptr_gray[3:2] != rptr_gray[3:2] (specifically inverted) and wptr_gray[1:0] == rptr_gray[1:0].
  // Actually, simpler check:
  // wfull is true if wptr_gray_next == {~rptr_gray_sync2[3:2], rptr_gray_sync2[1:0]}

  reg wfull_reg;
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wfull_reg <= 0;
    end else begin
      wfull_reg <= (wptr_gray_next == {~rptr_gray_sync2[PTR_WIDTH_PLUS_1-1:PTR_WIDTH_PLUS_1-2], rptr_gray_sync2[PTR_WIDTH_PLUS_1-3:0]});
    end
  end
  assign wfull = wfull_reg;

  // Read logic
  assign rptr_bin_next = rptr_bin + (rinc & ~rempty);
  assign rptr_gray_next = (rptr_bin_next >> 1) ^ rptr_bin_next;

  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rptr_bin <= 0;
      rptr_gray <= 0;
      wptr_gray_sync1 <= 0;
      wptr_gray_sync2 <= 0;
    end else begin
      rptr_bin <= rptr_bin_next;
      rptr_gray <= rptr_gray_next;
      wptr_gray_sync1 <= wptr_gray;
      wptr_gray_sync2 <= wptr_gray_sync1;
    end
  end

  // Read memory
  assign rdata = mem[rptr_bin[PTR_WIDTH-1:0]];

  // Empty detection
  // FIFO is empty when write pointer equals read pointer.
  reg rempty_reg;
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rempty_reg <= 1;
    end else begin
      rempty_reg <= (rptr_gray_next == wptr_gray_sync2);
    end
  end
  assign rempty = rempty_reg;

endmodule
